// StreamEndpoint is a client-side endpoint for streaming RPCs.
// It takes a request and returns a ClientStream for further operations.
type StreamEndpoint func(ctx context.Context, req interface{}) (streaming.ClientStream, error)

// UnaryEndpoint is a client-side endpoint specifically for unary (non-streaming) RPCs.
// This is semantically equivalent to Endpoint but provides clearer intent.
type UnaryEndpoint func(ctx context.Context, req, resp interface{}) error

// StreamRecvEndpoint is a client-side endpoint for receiving messages from a stream.
type StreamRecvEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) error

// EqualsTo compares two StreamRecvEndpoint by their function pointers.
func (e StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	return reflect.ValueOf(e).Pointer() == reflect.ValueOf(e2).Pointer()
}

// StreamSendEndpoint is a client-side endpoint for sending messages to a stream.
