		}
		o.StreamOptions = append(o.StreamOptions, streamOpt)
	}}
}

// WithTailOption adds tail options that apply after all other options.
// TailOptions are applied last in the middleware chain for fine-grained control.
func WithTailOption(opts ...TailOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
