// StreamOption is a function that configures stream-specific settings.
type StreamOption func(*client.Options)

// WithStreamOptions wraps multiple stream-specific options into a single Option.
// This allows grouping related streaming configurations together for cleaner code organization.
//
// Example:
//   client.WithStreamOptions(
//       client.WithStreamRecvTimeout(5*time.Second),
//       client.WithStreamMiddleware(myStreamMW),
//   )
func WithStreamOptions(opts ...StreamOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamOptions(...)")
		o.StreamOptions = append(o.StreamOptions, opts...)
	}}
}

// WithStreamRecvTimeout sets the receive timeout for streaming operations.
// If the receive timeout is exceeded during a stream recv operation, the operation
// will be canceled and an error will be returned.
//
// The timeout applies to each individual recv operation, not the entire stream lifetime.

